@app.cell
def _(asked, defined, mo, warehouse):
    answers = {q.id: warehouse.execute(q.uss_sql).pl() for q in asked}

    def glossary(q):
        return mo.md(
            "\n".join(
                f"- **{token}** — {defined[token]}" for token in q.defines if token in defined
            )
        )

    return answers, glossary


